from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            for y, x in q:
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if len(comp) != 4:
                continue
            minr = min(y for y,x in comp); maxr = max(y for y,x in comp)
            minc = min(x for y,x in comp); maxc = max(x for y,x in comp)
            norm = {(y-minr, x-minc) for y,x in comp}
            if (maxr-minr, maxc-minc) != (1,2):
                continue
            if norm == {(0,1),(1,0),(1,1),(1,2)}:
                up += 1
            elif norm == {(0,0),(0,1),(0,2),(1,1)}:
                down += 1
    out = [[0]*6 for _ in range(3)]
    slots = [(0,0),(2,0),(0,2),(2,2)]
    for n in range(up):
        if n < 4:
            r,c = slots[n]; out[r][c] = 3
    for n in range(down):
        if n < 4:
            r,c = slots[n]; out[r][c+3] = 1
    return out
